//! Host-side M0 prototype for a Noise-based tablet-to-Home Assistant pairing session.
//!
//! The caller supplies static private keys and already authenticated peer public keys. This
//! crate uses those keys; it does not establish trust in a key received through an untrusted
//! channel, persist keys, perform enrollment, or provide a hardware integration. Ephemeral keys
//! for each connection are generated by Snow's configured operating-system random source.
//!
//! The initiator is expected to be the tablet and the responder the Home Assistant host. The
//! Noise IK handshake pins the responder key at the initiator and checks the expected tablet key
//! at the responder before returning the responder handshake message. Both sides bind protocol
//! version 1 and the caller-supplied 32-byte pairing/session context into the Noise prologue.
//!
//! Each transport frame is one Noise transport message. The caller must preserve message
//! boundaries and reliable ordering. This crate does not add a stream framing format.

use std::error::Error;
use std::fmt::{Display, Formatter};
use std::mem;

use snow::{Builder, HandshakeState, TransportState};

/// Largest grant message `open_one_way` accepts: far above a refresh token, far below memory.
pub const MAX_ONE_WAY_MESSAGE: usize = 1024;

const ONE_WAY_PATTERN: &str = "Noise_N_25519_ChaChaPoly_SHA256";

/// Opens one message that Home Assistant sealed to this tablet's static key (plan 004).
///
/// The sender is anonymous: `Noise_N` proves only that whoever wrote the message knew the
/// tablet's public key and the `prologue`, which binds it to its purpose. The caller must treat
/// the plaintext as unauthenticated and check it against what it expects. The pattern has no
/// replay protection either; a repeated message opens to the same plaintext.
///
/// # Errors
/// [`PairingError::FrameTooLarge`] for a message over [`MAX_ONE_WAY_MESSAGE`],
/// [`PairingError::HandshakeFailed`] for a message that does not open with this key and prologue,
/// and [`PairingError::CryptoUnavailable`] if Snow cannot start.
pub fn open_one_way(
    static_private: &[u8; 32],
    prologue: &[u8],
    message: &[u8],
) -> Result<Vec<u8>, PairingError> {
    if message.len() > MAX_ONE_WAY_MESSAGE {
        return Err(PairingError::FrameTooLarge);
    }
    let params = ONE_WAY_PATTERN
        .parse()
        .map_err(|_| PairingError::CryptoUnavailable)?;
    let mut handshake = Builder::new(params)
        .local_private_key(static_private)
        .map_err(|_| PairingError::CryptoUnavailable)?
        .prologue(prologue)
        .map_err(|_| PairingError::CryptoUnavailable)?
        .build_responder()
        .map_err(|_| PairingError::CryptoUnavailable)?;
    let mut plaintext = vec![0_u8; MAX_ONE_WAY_MESSAGE];
    let length = handshake
        .read_message(message, &mut plaintext)
        .map_err(|_| PairingError::HandshakeFailed)?;
    plaintext.truncate(length);
    Ok(plaintext)
}

/// Maximum plaintext size for one encrypted transport frame.
pub const MAX_FRAME_PLAINTEXT: usize = 4096;

const NOISE_PATTERN: &str = "Noise_IK_25519_ChaChaPoly_SHA256";
const PROTOCOL_DOMAIN: &[u8] = b"njorun/pairing";
const PROTOCOL_VERSION: u8 = 1;
const CONTEXT_LEN: usize = 32;
const CHACHA_POLY_TAG_LEN: usize = 16;
const MAX_FRAME_CIPHERTEXT: usize = MAX_FRAME_PLAINTEXT + CHACHA_POLY_TAG_LEN;
const HANDSHAKE_MESSAGE_LEN: usize = 96;
const HANDSHAKE_RESPONSE_LEN: usize = 48;
const HANDSHAKE_BUFFER_LEN: usize = 256;

/// The X25519 public key of a static private key, as the peer pins it.
///
/// # Errors
/// Returns [`PairingError::CryptoUnavailable`] if Snow has no Curve25519 implementation.
pub fn public_key(static_private: &[u8; 32]) -> Result<[u8; 32], PairingError> {
    use snow::params::DHChoice;
    use snow::resolvers::{CryptoResolver, DefaultResolver};

    let mut dh = DefaultResolver
        .resolve_dh(&DHChoice::Curve25519)
        .ok_or(PairingError::CryptoUnavailable)?;
    dh.set(static_private);
    dh.pubkey()
        .try_into()
        .map_err(|_| PairingError::CryptoUnavailable)
}

/// Errors produced while establishing or using a pairing session.
///
/// [`Display`] uses fixed diagnostics that do not include keys, frames, or
/// other caller-provided data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PairingError {
    /// Snow could not initialize its Noise implementation or random source.
    CryptoUnavailable,
    /// The operation is not valid in the endpoint's current handshake phase.
    WrongPhase,
    /// The peer's static public key does not match the configured expected key.
    PeerMismatch,
    /// A Noise handshake message was malformed, unauthenticated, or used a different context.
    HandshakeFailed,
    /// A plaintext or ciphertext frame exceeds the configured maximum size.
    FrameTooLarge,
    /// A transport frame failed authentication, including a corrupted or replayed frame.
    FrameAuthenticationFailed,
    /// Snow failed while encrypting a transport frame.
    FrameProtectionFailed,
    /// The endpoint was closed after a cryptographic failure or peer mismatch.
    Closed,
}

impl Display for PairingError {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> std::fmt::Result {
        let message = match self {
            Self::CryptoUnavailable => "Noise cryptography is unavailable",
            Self::WrongPhase => "operation is invalid in the current handshake phase",
            Self::PeerMismatch => "peer static key does not match the expected key",
            Self::HandshakeFailed => "Noise handshake failed",
            Self::FrameTooLarge => "transport frame exceeds the maximum size",
            Self::FrameAuthenticationFailed => "transport frame authentication failed",
            Self::FrameProtectionFailed => "transport frame encryption failed",
            Self::Closed => "pairing session is closed",
        };
        formatter.write_str(message)
    }
}

impl Error for PairingError {}

enum Phase {
    InitiatorReady(HandshakeState),
    InitiatorWaiting(HandshakeState),
    ResponderReady(HandshakeState),
    Established(TransportState),
    Closed,
}

struct Endpoint {
    phase: Phase,
    expected_peer_static: [u8; 32],
}

impl Endpoint {
    fn start(&mut self) -> Result<Vec<u8>, PairingError> {
        let phase = mem::replace(&mut self.phase, Phase::Closed);
        match phase {
            Phase::InitiatorReady(mut handshake) => {
                let mut message = [0_u8; HANDSHAKE_BUFFER_LEN];
                let Ok(written) = handshake.write_message(&[], &mut message) else {
                    return Err(PairingError::HandshakeFailed);
                };
                if written != HANDSHAKE_MESSAGE_LEN {
                    return Err(PairingError::HandshakeFailed);
                }
                self.phase = Phase::InitiatorWaiting(handshake);
                Ok(message[..written].to_vec())
            }
            other_phase => {
                let error = phase_error(&other_phase);
                self.phase = other_phase;
                Err(error)
            }
        }
    }

    fn finish(&mut self, response: &[u8]) -> Result<(), PairingError> {
        let phase = mem::replace(&mut self.phase, Phase::Closed);
        match phase {
            Phase::InitiatorWaiting(mut handshake) => {
                if response.len() != HANDSHAKE_RESPONSE_LEN {
                    return Err(PairingError::HandshakeFailed);
                }
                let mut payload = [0_u8; HANDSHAKE_BUFFER_LEN];
                let Ok(payload_len) = handshake.read_message(response, &mut payload) else {
                    return Err(PairingError::HandshakeFailed);
                };
                if payload_len != 0 || !handshake.is_handshake_finished() {
                    return Err(PairingError::HandshakeFailed);
                }
                if !remote_static_matches(&handshake, &self.expected_peer_static) {
                    return Err(PairingError::PeerMismatch);
                }
                let Ok(transport) = handshake.into_transport_mode() else {
                    return Err(PairingError::HandshakeFailed);
                };
                self.phase = Phase::Established(transport);
                Ok(())
            }
            other_phase => {
                let error = phase_error(&other_phase);
                self.phase = other_phase;
                Err(error)
            }
        }
    }

    fn respond(&mut self, request: &[u8]) -> Result<Vec<u8>, PairingError> {
        let phase = mem::replace(&mut self.phase, Phase::Closed);
        match phase {
            Phase::ResponderReady(mut handshake) => {
                if request.len() != HANDSHAKE_MESSAGE_LEN {
                    return Err(PairingError::HandshakeFailed);
                }
                let mut payload = [0_u8; HANDSHAKE_BUFFER_LEN];
                let Ok(payload_len) = handshake.read_message(request, &mut payload) else {
                    return Err(PairingError::HandshakeFailed);
                };
                if payload_len != 0 || handshake.is_handshake_finished() {
                    return Err(PairingError::HandshakeFailed);
                }
                if !remote_static_matches(&handshake, &self.expected_peer_static) {
                    return Err(PairingError::PeerMismatch);
                }

                let mut response = [0_u8; HANDSHAKE_BUFFER_LEN];
                let Ok(written) = handshake.write_message(&[], &mut response) else {
                    return Err(PairingError::HandshakeFailed);
                };
                if written != HANDSHAKE_RESPONSE_LEN || !handshake.is_handshake_finished() {
                    return Err(PairingError::HandshakeFailed);
                }
                let Ok(transport) = handshake.into_transport_mode() else {
                    return Err(PairingError::HandshakeFailed);
                };
                self.phase = Phase::Established(transport);
                Ok(response[..written].to_vec())
            }
            other_phase => {
                let error = phase_error(&other_phase);
                self.phase = other_phase;
                Err(error)
            }
        }
    }

    fn seal_frame(&mut self, plaintext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.ensure_established()?;
        if plaintext.len() > MAX_FRAME_PLAINTEXT {
            return Err(PairingError::FrameTooLarge);
        }

        self.with_transport(|transport| {
            let mut ciphertext = vec![0_u8; plaintext.len() + CHACHA_POLY_TAG_LEN];
            let written = transport
                .write_message(plaintext, &mut ciphertext)
                .map_err(|_| PairingError::FrameProtectionFailed)?;
            ciphertext.truncate(written);
            Ok(ciphertext)
        })
    }

    fn open_frame(&mut self, ciphertext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.ensure_established()?;
        if ciphertext.len() > MAX_FRAME_CIPHERTEXT {
            return Err(PairingError::FrameTooLarge);
        }

        self.with_transport(|transport| {
            let plaintext_capacity = ciphertext.len().saturating_sub(CHACHA_POLY_TAG_LEN);
            let mut plaintext = vec![0_u8; plaintext_capacity];
            let written = transport
                .read_message(ciphertext, &mut plaintext)
                .map_err(|_| PairingError::FrameAuthenticationFailed)?;
            plaintext.truncate(written);
            Ok(plaintext)
        })
    }

    const fn is_established(&self) -> bool {
        matches!(self.phase, Phase::Established(_))
    }

    const fn ensure_established(&self) -> Result<(), PairingError> {
        if self.is_established() {
            Ok(())
        } else {
            Err(phase_error(&self.phase))
        }
    }

    fn with_transport<T>(
        &mut self,
        operation: impl FnOnce(&mut TransportState) -> Result<T, PairingError>,
    ) -> Result<T, PairingError> {
        let phase = mem::replace(&mut self.phase, Phase::Closed);
        match phase {
            Phase::Established(mut transport) => {
                let result = operation(&mut transport);
                if result.is_ok() {
                    self.phase = Phase::Established(transport);
                }
                result
            }
            other_phase => {
                let error = phase_error(&other_phase);
                self.phase = other_phase;
                Err(error)
            }
        }
    }
}

/// Tablet-side Noise IK initiator.
///
/// The trusted Home Assistant public key must have been authenticated by the application before
/// it is passed here. This type does not authenticate an initial key obtained from an untrusted
/// source.
pub struct Initiator {
    endpoint: Endpoint,
}

impl Initiator {
    /// Creates an initiator using caller-provided static keys and pairing/session context.
    ///
    /// Snow generates a fresh ephemeral key during each handshake using its operating-system
    /// random source. The private key and public key are borrowed only while building the endpoint.
    ///
    /// # Errors
    /// Returns [`PairingError::CryptoUnavailable`] if Snow cannot initialize the Noise pattern or
    /// its random source.
    pub fn new(
        tablet_static_private: &[u8; 32],
        trusted_ha_static_public: &[u8; 32],
        pairing_session_context: &[u8; CONTEXT_LEN],
    ) -> Result<Self, PairingError> {
        let prologue = make_prologue(pairing_session_context);
        let params = NOISE_PATTERN
            .parse()
            .map_err(|_| PairingError::CryptoUnavailable)?;
        let handshake = Builder::new(params)
            .local_private_key(tablet_static_private)
            .map_err(|_| PairingError::CryptoUnavailable)?
            .remote_public_key(trusted_ha_static_public)
            .map_err(|_| PairingError::CryptoUnavailable)?
            .prologue(&prologue)
            .map_err(|_| PairingError::CryptoUnavailable)?
            .build_initiator()
            .map_err(|_| PairingError::CryptoUnavailable)?;

        Ok(Self {
            endpoint: Endpoint {
                phase: Phase::InitiatorReady(handshake),
                expected_peer_static: *trusted_ha_static_public,
            },
        })
    }

    /// Creates the first Noise IK handshake message for the responder.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] if the handshake has already advanced, or
    /// [`PairingError::HandshakeFailed`] if Snow fails while creating the message.
    pub fn start(&mut self) -> Result<Vec<u8>, PairingError> {
        self.endpoint.start()
    }

    /// Verifies the responder's message and enables encrypted transport frames.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] if the first handshake message has not been created,
    /// [`PairingError::PeerMismatch`] if the responder static key differs from the configured
    /// key, or [`PairingError::HandshakeFailed`] if the response fails Noise authentication or
    /// uses a different prologue. A cryptographic failure closes this endpoint.
    pub fn finish(&mut self, response: &[u8]) -> Result<(), PairingError> {
        self.endpoint.finish(response)
    }

    /// Encrypts one plaintext into a single ordered transport frame.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] until the handshake completes,
    /// [`PairingError::FrameTooLarge`] if `plaintext` exceeds
    /// [`MAX_FRAME_PLAINTEXT`], [`PairingError::FrameProtectionFailed`] if encryption fails, or
    /// [`PairingError::Closed`] after a previous cryptographic failure.
    pub fn seal_frame(&mut self, plaintext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.endpoint.seal_frame(plaintext)
    }

    /// Decrypts one ordered transport frame.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] until the handshake completes,
    /// [`PairingError::FrameTooLarge`] if the ciphertext exceeds the maximum frame size,
    /// [`PairingError::FrameAuthenticationFailed`] for corrupted or replayed ciphertext, or
    /// [`PairingError::Closed`] after a previous cryptographic failure.
    ///
    /// Authentication failures close this endpoint.
    pub fn open_frame(&mut self, ciphertext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.endpoint.open_frame(ciphertext)
    }

    /// Reports whether this endpoint's local Noise handshake completed.
    ///
    /// This does not report peer liveness or prove mutual handshake confirmation.
    #[must_use]
    pub const fn is_established(&self) -> bool {
        self.endpoint.is_established()
    }
}

/// Home Assistant-side Noise IK responder.
///
/// The expected tablet public key must have been authenticated by the application before it is
/// passed here. The responder checks that static key after reading the initiator message and
/// before producing a response or enabling transport.
pub struct Responder {
    endpoint: Endpoint,
}

impl Responder {
    /// Creates a responder using a caller-provided static private key, expected tablet public key,
    /// and pairing/session context.
    ///
    /// Snow generates a fresh ephemeral key during each handshake using its operating-system
    /// random source. This crate does not persist the supplied key material.
    ///
    /// # Errors
    /// Returns [`PairingError::CryptoUnavailable`] if Snow cannot initialize the Noise pattern or
    /// its random source.
    pub fn new(
        ha_static_private: &[u8; 32],
        expected_tablet_static_public: &[u8; 32],
        pairing_session_context: &[u8; CONTEXT_LEN],
    ) -> Result<Self, PairingError> {
        let prologue = make_prologue(pairing_session_context);
        let params = NOISE_PATTERN
            .parse()
            .map_err(|_| PairingError::CryptoUnavailable)?;
        let handshake = Builder::new(params)
            .local_private_key(ha_static_private)
            .map_err(|_| PairingError::CryptoUnavailable)?
            .prologue(&prologue)
            .map_err(|_| PairingError::CryptoUnavailable)?
            .build_responder()
            .map_err(|_| PairingError::CryptoUnavailable)?;

        Ok(Self {
            endpoint: Endpoint {
                phase: Phase::ResponderReady(handshake),
                expected_peer_static: *expected_tablet_static_public,
            },
        })
    }

    /// Checks the tablet static key and creates the final handshake response.
    ///
    /// Once this returns successfully, the responder may use encrypted frames. The application
    /// must receive an authenticated initiator transport message before applying enrollment or
    /// management effects. Returning the response only completes the responder's local Noise
    /// state; it does not confirm that the initiator received the response or completed the
    /// handshake.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] if the responder has already advanced,
    /// [`PairingError::PeerMismatch`] if the initiator static key differs from the configured
    /// key, or [`PairingError::HandshakeFailed`] if the request fails Noise authentication, has a
    /// different prologue, or is malformed. A peer mismatch or cryptographic failure closes this
    /// endpoint.
    pub fn respond(&mut self, request: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.endpoint.respond(request)
    }

    /// Encrypts one plaintext into a single ordered transport frame.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] until the handshake completes,
    /// [`PairingError::FrameTooLarge`] if `plaintext` exceeds
    /// [`MAX_FRAME_PLAINTEXT`], [`PairingError::FrameProtectionFailed`] if encryption fails, or
    /// [`PairingError::Closed`] after a previous cryptographic failure.
    pub fn seal_frame(&mut self, plaintext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.endpoint.seal_frame(plaintext)
    }

    /// Decrypts one ordered transport frame.
    ///
    /// # Errors
    /// Returns [`PairingError::WrongPhase`] until the handshake completes,
    /// [`PairingError::FrameTooLarge`] if the ciphertext exceeds the maximum frame size,
    /// [`PairingError::FrameAuthenticationFailed`] for corrupted or replayed ciphertext, or
    /// [`PairingError::Closed`] after a previous cryptographic failure.
    ///
    /// Authentication failures close this endpoint.
    pub fn open_frame(&mut self, ciphertext: &[u8]) -> Result<Vec<u8>, PairingError> {
        self.endpoint.open_frame(ciphertext)
    }

    /// Reports whether this endpoint's local Noise handshake completed.
    ///
    /// This does not report peer liveness or prove that the initiator received the responder's
    /// handshake response. Require an authenticated initiator transport message before applying
    /// enrollment or management effects.
    #[must_use]
    pub const fn is_established(&self) -> bool {
        self.endpoint.is_established()
    }
}

fn make_prologue(context: &[u8; CONTEXT_LEN]) -> Vec<u8> {
    let mut prologue = Vec::with_capacity(PROTOCOL_DOMAIN.len() + 1 + context.len());
    prologue.extend_from_slice(PROTOCOL_DOMAIN);
    prologue.push(PROTOCOL_VERSION);
    prologue.extend_from_slice(context);
    prologue
}

fn remote_static_matches(handshake: &HandshakeState, expected: &[u8; 32]) -> bool {
    handshake
        .get_remote_static()
        .is_some_and(|actual| actual == expected)
}

const fn phase_error(phase: &Phase) -> PairingError {
    match phase {
        Phase::Closed => PairingError::Closed,
        Phase::InitiatorReady(_)
        | Phase::InitiatorWaiting(_)
        | Phase::ResponderReady(_)
        | Phase::Established(_) => PairingError::WrongPhase,
    }
}
